pageCss:
.subpage-hero {
  background: linear-gradient(135deg, var(--navy-dark) 0%, #1B3A5C 100%);
  padding: 160px 48px 80px;
  text-align: center;
}
.subpage-hero .section-label { color: rgba(255,255,255,0.5); }
.subpage-hero h1 {
  font-size: clamp(32px, 5vw, 52px);
  font-weight: 900;
  color: var(--white);
  letter-spacing: -0.03em;
  line-height: 1.1;
  margin-bottom: 16px;
}
.subpage-hero p {
  font-size: 18px;
  color: rgba(255,255,255,0.65);
  max-width: 620px;
  margin: 0 auto;
  line-height: 1.65;
}
.report-body {
  padding: 80px 48px 120px;
  background: var(--cream);
}
.report-body .container {
  max-width: 760px;
  margin: 0 auto;
}
.report-section {
  margin-bottom: 56px;
}
.report-section h2 {
  font-family: var(--font-serif);
  font-size: 26px;
  font-weight: 800;
  color: var(--navy-dark);
  letter-spacing: -0.01em;
  margin-bottom: 20px;
  padding-bottom: 12px;
  border-bottom: 2px solid rgba(0,0,0,0.08);
}
.report-section h3 {
  font-size: 18px;
  font-weight: 800;
  color: var(--red);
  letter-spacing: -0.01em;
  margin: 32px 0 12px;
}
.report-section h3:first-of-type { margin-top: 0; }
.report-section p {
  font-size: 16.5px;
  line-height: 1.8;
  color: #2c2c2c;
  margin-bottom: 18px;
}
.report-section p:last-child { margin-bottom: 0; }
.report-section ul {
  margin: 0 0 18px 20px;
  padding: 0;
}
.report-section ul li {
  font-size: 16.5px;
  line-height: 1.75;
  color: #2c2c2c;
  margin-bottom: 10px;
}
.report-callout {
  background: var(--white);
  border-left: 4px solid var(--red);
  border-radius: 6px;
  padding: 20px 24px;
  margin: 20px 0;
}
.report-callout p {
  font-size: 15.5px;
  line-height: 1.7;
  color: #2c2c2c;
  margin: 0;
}
.report-callout .callout-label {
  display: block;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 8px;
}
.report-callout-dark {
  background: var(--navy-dark);
  border-left: 4px solid var(--gold, #C9A24B);
  border-radius: 6px;
  padding: 20px 24px;
  margin: 20px 0;
}
.report-callout-dark p {
  font-size: 15.5px;
  line-height: 1.7;
  color: rgba(255,255,255,0.9);
  margin: 0;
}
.report-callout-dark .callout-label {
  display: block;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.6);
  margin-bottom: 8px;
}
.report-table-wrap {
  overflow-x: auto;
  margin: 20px 0;
  border-radius: 8px;
  border: 1px solid var(--gray-200);
}
.report-table {
  width: 100%;
  border-collapse: collapse;
  background: var(--white);
  font-size: 14px;
}
.report-table th {
  background: var(--navy-dark);
  color: var(--white);
  text-align: left;
  padding: 12px 14px;
  font-size: 12px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.report-table td {
  padding: 12px 14px;
  border-top: 1px solid var(--gray-200);
  color: #2c2c2c;
  line-height: 1.55;
  vertical-align: top;
}
.report-table td:first-child { font-weight: 700; color: var(--navy-dark); white-space: nowrap; }
@media (max-width: 600px) {
  .subpage-hero { padding: 140px 24px 64px; }
  .report-body { padding: 56px 24px 80px; }
  .report-section h2 { font-size: 22px; }
}
